// Devuelve al orquestador solo la descripción (o el error del agente).
const resultado = $input.first().json;
if (resultado.error) return [{ json: { descripcion: '', error: 'El agente redactor no está disponible.' } }];
const descripcion = String(resultado.output ?? '').replace(/^["'\s]+|["'\s]+$/g, '').slice(0, 1500);
return [{ json: { descripcion } }];
